import {SOURCES,ELEMENTS,TEAMS,ANIIMO,BUILDS,INITIAL_COLLECTION,STAT_NAMES,DEFAULT_PROFILE,ROLE_PRIORITIES,ITEMS,getAniimo,getElement,getBuild} from './data.js';
const STORAGE='aniimo-center:v1';
const safe = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,min,max,fallback=min)=>{const x=Number(v);return Number.isFinite(x)?Math.max(min,Math.min(max,Math.floor(x))):fallback};
const clone=o=>JSON.parse(JSON.stringify(o));
const initial={collection:clone(INITIAL_COLLECTION),favorite:'All',target:'Lightning',objective:'Balanced',rosterFilter:'All',rosterQuery:'',rosterOwned:false,onlyOwned:false,selected:'',teamNames:['','','',''],nav:'overview',compare:false};
function readState(){try{const prev=JSON.parse(localStorage.getItem(STORAGE));if(prev&&typeof prev==='object'&&prev.collection&&typeof prev.collection==='object'&&!Array.isArray(prev.collection)){
 // The v1 screenshot was a demo, not an assertion of ownership. Remove only the exact unedited fixture.
 const collection={...prev.collection};const demo=collection.Fulmintis;
 if(demo?.notes==='Imported from screenshots (27 Oct 2026).'&&demo.level===60&&demo.cp===3388&&demo.star===6&&demo.spent===22&&demo.budget===43&&demo.awaken?.ATK===20&&demo.awaken?.REGEN===20&&demo.held===''&&demo.potential==='Perfect')delete collection.Fulmintis;
 const selected=prev.selected==='Fulmintis'&&!collection.Fulmintis?'':prev.selected;
 const teamNames=Array.isArray(prev.teamNames)&&prev.teamNames.join('|')==='Fulmintis|Dazmand|Luminelle|Besauce'?['','','','']:prev.teamNames;
 return {...clone(initial),...prev,collection,selected,teamNames,nav:'overview',rosterQuery:'',rosterOwned:false,compare:false};
 }}catch{}return clone(initial)}
let state=readState(), modal=null, toastTimer;
const app=document.getElementById('app');
const countOwned=()=>ANIIMO.filter(a=>state.collection[a.name]?.owned).length;
const owned=name=>!!state.collection[name]?.owned;
const source=id=>SOURCES.find(s=>s.id===id);
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({...state,nav:'overview',rosterQuery:'',compare:false}));}catch{flash('Browser storage unavailable. Export your data before closing.','warn')}}
function flash(msg,type='info'){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent=msg;t.className='toast show '+type;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
function icon(name,size=18){const p={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 team:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2"/><path d="M17 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',
 book:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 11h8M8 15h5"/>',
 chart:'<path d="M4 20V4M4 20h16M8 16l4-5 3 2 5-8"/>',
 layers:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',
 database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v7c0 2 4 4 9 4s9-2 9-4V5M3 12v7c0 2 4 3 9 3s9-1 9-3v-7"/>',
 search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 x:'<path d="M5 5 19 19M19 5 5 19"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 upload:'<path d="M12 21V8m-5 5 5-5 5 5M4 7V3h16v4"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 shield:'<path d="M12 2 20 6v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 edit:'<path d="m4 16-1 5 5-1L20 8l-4-4L4 16zM14 6l4 4"/>',
 external:'<path d="M14 4h6v6M20 4l-9 9M20 14v6H4V4h6"/>',
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 save:'<path d="M4 3h14l3 3v15H3V3h1zm3 0v7h10V3M7 21v-8h10v8"/>',
 alert:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 4h.01"/>',
 refresh:'<path d="M3 10a9 9 0 0 1 15-5l3 3M21 14a9 9 0 0 1-15 5l-3-3M21 3v5h-5M3 21v-5h5"/>',
 heart:'<path d="M20.8 4.8c-2-2-5-2-7 0L12 6.6l-1.8-1.8c-2-2-5-2-7 0s-2 5 0 7L12 21l8.8-9.2c2-2 2-5 0-7Z"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.spark}</svg>`}
const NAV=[['overview','Command deck','grid'],['teams','Elemental teams','team'],['aniidex','Aniimo library','book'],['items','Held item lab','spark'],['progression','Upgrade roadmap','chart'],['planner','Build planner','chart'],['collection','My collection','layers'],['sources','Sources & data','database']];
function elBadge(name,small=false){let e=getElement(name);return `<span class="element ${small?'tiny':''}" style="--element:${e.tone}"><span>${safe(e.symbol)}</span>${safe(name)}</span>`}
function avatar(a,size='md'){let e=getElement(a.element);return `<span class="avatar ${size}" style="--unit-color:${e.tone};--unit-symbol:'${e.symbol}'"><span class="avatar-halo"></span><span class="avatar-rune">${safe(e.symbol)}</span><span class="avatar-initial">${safe(a.monogram)}</span></span>`}
function unitCard(name,role,form,opts={}){const a=getAniimo(name)||{name,element:'Lightning',monogram:name.slice(0,2).toUpperCase(),role:role||'Support'};return `<button class="unit-card ${opts.compact?'compact':''}" data-open="${safe(name)}" aria-label="Open ${safe(name)} build"><div class="unit-visual">${avatar(a,opts.compact?'sm':'md')}<span class="unit-owned ${owned(name)?'yes':''}" title="${owned(name)?'Owned':'Not in collection'}">${owned(name)?icon('check',12):icon('plus',12)}</span></div><span class="unit-name">${safe(name)}</span><span class="unit-role">${safe(role||a.role)}${form&&form!=='Basic'?` · ${safe(form)}`:''}</span></button>`}
const button=(title,nav,cls='btn secondary',suffix='arrow')=>`<button class="${cls}" data-nav="${nav}">${title} ${icon(suffix,16)}</button>`;
function header(){return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark"><span class="brand-bolt">ϟ</span></span><div><strong>ANIIMO<span>CENTER</span></strong><small>OPTIMIZATION COMMAND</small></div></div><div class="side-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation">${NAV.map(([id,title,i])=>`<button data-nav="${id}" class="nav-link ${state.nav===id?'active':''}">${icon(i,19)}<span>${title}</span>${state.nav===id?'<span class="nav-active-dot"></span>':''}</button>`).join('')}</nav><div class="sidebar-lower"><div class="signal-card"><div class="signal-head"><span class="signal-dot"></span> FIELD INTELLIGENCE</div><b>Research snapshot</b><span>Reviewed 27 Oct 2026</span><div class="mini-track"><i></i></div><small>Source-backed • not live API</small></div><div class="sidebar-footer">INDEPENDENT FAN TOOL <span>V 1.0</span></div></div></aside><div class="main-area"><header class="topbar"><button class="mobile-brand" data-toggle="menu" aria-label="Open menu">${icon('menu',22)}<strong>ANIIMO<span>CENTER</span></strong></button><div class="crumb">OPERATIONS <span>/</span> ${NAV.find(x=>x[0]===state.nav)?.[1].toUpperCase()}</div><div class="top-actions"><span class="top-status"><i></i> CURATED DATA • OCT '26</span><button class="pill-btn" data-nav="collection" title="My collection">${icon('layers',16)} <span>${countOwned()} owned</span></button><span class="top-avatar" title="Independent Aniimo fan tool">AC</span></div></header><main id="main" tabindex="-1">`}
function footer(){return `</main><footer class="page-footer"><span>ANIIMO CENTER <span class="muted">· Independent fan-made optimizer · Not affiliated with Aniimo</span></span><span>Last curated review: 27 OCT 2026</span></footer></div><div id="mobile-overlay" data-toggle="menu"></div></div>`}
function title(label,heading,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="microline"></span>${label}</div><h1>${heading}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function statusRow(label,val,sub){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${val}</div><div class="metric-sub">${sub}</div></div>`}
function teamPreview(team){const e=getElement(team.element);return `<div class="team-preview" style="--team-tone:${e.tone}"><div class="team-preview-head"><div>${elBadge(team.element)}<h3>${safe(team.name)}</h3></div><span class="badge thin">${safe(team.tag)}</span></div><p>${safe(team.summary)}</p><div class="preview-units">${team.lineup.map(([name,role])=>{const a=getAniimo(name);return `<button class="preview-unit" data-open="${safe(name)}" title="${safe(name)} — ${safe(role)}">${avatar(a,'sm')}<span>${safe(name)}</span></button>`}).join('')}</div><button class="text-action" data-team="${safe(team.element)}">View composition ${icon('arrow',15)}</button></div>`}
function overview(){const researched=Object.keys(BUILDS).length;const ownedCount=countOwned();const picks=['Fire','Grass','Dark'].map(id=>TEAMS.find(t=>t.element===id)).filter(Boolean);return `${title('COMMAND CENTER / 001','Every element. <em>Every advantage.</em>','Explore elemental synergies, find your Aniimo’s best-documented build, compare held items, and plan awakenings with evidence — not guesses.',button('Open Aniimo library','aniidex','btn primary'))}<section class="hero-grid universal-hero"><div class="hero-panel"><div class="hero-noise"></div><div class="hero-content"><span class="hero-tag"><span class="sparkdot"></span> ALL NINE ELEMENTS / BUILD INTELLIGENCE</span><h2>BUILD THE<br><span class="hero-highlight">BEST TEAM.</span></h2><p>Find the right lineup for an encounter. Then tune each Aniimo’s skills, held items, capability awakenings, and star-up investments.</p><div class="hero-chips"><span class="glass-chip">9 ELEMENTAL PATHS</span><span class="glass-chip">SOURCE-ATTRIBUTED GUIDES</span><span class="glass-chip">PERSONAL ROSTER OPTIONAL</span></div><div class="hero-buttons"><button class="btn light" data-nav="teams">Explore all teams ${icon('arrow',17)}</button><button class="btn ghost" data-nav="progression">Plan an awakening ${icon('chart',17)}</button></div></div><div class="hero-art universal-art" aria-hidden="true"><div class="universe-ring outer"></div><div class="universe-ring inner"></div><div class="universe-core"><strong>9</strong><small>ELEMENTS</small></div>${ELEMENTS.map((e,i)=>`<div class="universe-node" style="--i:${i};--node:${e.tone}"><span>${e.symbol}</span></div>`).join('')}</div><div class="hero-corner">ALL-ELEMENT META / CURATED RESEARCH</div></div><div class="hero-stats">${statusRow('ELEMENTAL TEAMS',String(TEAMS.length).padStart(2,'0'),'Element-by-element strategies')}${statusRow('ANIIMO INDEXED',String(ANIIMO.length),'Growing curated roster')}${statusRow('HELD ITEMS',String(ITEMS.length).padStart(2,'0'),'Equipment reference')}${statusRow('GUIDED BUILDS',String(researched).padStart(2,'0'),'Individual research profiles')}</div></section><section class="command-start"><div><span class="section-kicker">YOUR WORKSPACE</span><h2>${ownedCount?`${ownedCount} Aniimo tracked`:'Start with any Aniimo'}</h2><p>${ownedCount?'Your collection is saved locally. Discover gaps in your elemental coverage, then plan your next investment.':'Browsing doesn’t require a collection. Add Aniimo only when you want to track your own progress.'}</p></div><div class="command-start-actions"><button class="btn secondary" data-nav="collection">${icon('layers',16)} ${ownedCount?'View my collection':'Create my collection'}</button><button class="btn subtle" data-nav="planner">${icon('team',16)} Open squad planner</button></div></section><section class="overview-columns"><div class="section-block"><div class="section-heading"><div><span class="section-kicker">ELEMENT MATCHUPS</span><h2>Choose a combat element</h2></div>${button('Compare teams','teams','btn subtle')}</div><div class="element-grid">${ELEMENTS.map(e=>`<button class="element-tile" style="--tile:${e.tone}" data-team="${e.id}"><span class="tile-icon">${e.symbol}</span><strong>${e.id}</strong><small>${TEAMS.find(t=>t.element===e.id)?.name||''}</small>${icon('chevron',17)}</button>`).join('')}</div><div class="section-heading second"><div><span class="section-kicker">MULTI-ELEMENT EXAMPLES</span><h2>Explore different strategies</h2></div></div><div class="overview-mini-teams">${picks.map(teamPreview).join('')}</div><div class="field-note">${icon('info',20)}<p><strong>Not a tier-list verdict.</strong> These are published team examples; the strongest option depends on the boss, forms, skills, equipment, and patch.</p></div></div><div class="section-block"><div class="section-heading"><div><span class="section-kicker">HOW TO OPTIMIZE</span><h2>Five steps to a stronger squad</h2></div></div><div class="checklist"><div class="check-item"><span class="check-sign">${icon('team',18)}</span><div><b>01 · Choose an elemental team</b><p>Start with enemy weaknesses and what your roster can cover.</p><button class="mini-link" data-nav="teams">Browse teams ${icon('arrow',14)}</button></div><span class="check-state">TEAM</span></div><div class="check-item"><span class="check-sign">${icon('book',18)}</span><div><b>02 · Open each Aniimo build</b><p>Check role, skills, personality, form, and the recommendation’s confidence.</p><button class="mini-link" data-nav="aniidex">Search library ${icon('arrow',14)}</button></div><span class="check-state">BUILD</span></div><div class="check-item"><span class="check-sign">${icon('spark',18)}</span><div><b>03 · Select held items</b><p>Compare documented effects to actual skill and team synergy.</p><button class="mini-link" data-nav="items">Compare items ${icon('arrow',14)}</button></div><span class="check-state">GEAR</span></div><div class="check-item"><span class="check-sign">${icon('chart',18)}</span><div><b>04 · Plan awakening and Star Up</b><p>Prioritize role scaling and useful breakpoints before committing materials.</p><button class="mini-link" data-nav="progression">Upgrade roadmap ${icon('arrow',14)}</button></div><span class="check-state">GROW</span></div><div class="check-item"><span class="check-sign">${icon('layers',18)}</span><div><b>05 · Track only what you own</b><p>Record personal stats whenever you're ready; no demo units or guessed levels.</p><button class="mini-link" data-nav="collection">My collection ${icon('arrow',14)}</button></div><span class="check-state">SAVE</span></div></div><div class="field-note">${icon('info',20)}<p><strong>Evidence first.</strong> Detailed guides, community-tested builds, and general role templates are visibly distinguished. No simulated DPS or invented best-in-slot claims.</p></div></div></section>`}
function teamsPage(){const current=TEAMS.find(t=>t.element===state.target)||TEAMS[0];const e=getElement(current.element);const line=current.lineup;const own=line.filter(r=>owned(r[0])).length;return `${title('TEAM ARCHITECT / 002','Elemental <em>team lab.</em>','Explore nine researched compositions, role coverage, substitutions, and proven rotation ideas.',button('Build custom squad','planner','btn primary'))}<div class="filter-head"><div class="filter-label">SELECT YOUR ELEMENT <span>09 TYPES</span></div><div class="elements-strip">${ELEMENTS.map(ele=>`<button data-team="${ele.id}" class="element-switch ${current.element===ele.id?'chosen':''}" style="--tile:${ele.tone}"><span>${ele.symbol}</span>${ele.id}</button>`).join('')}</div></div><div class="team-detail" style="--team-tone:${e.tone}"><div class="detail-background"></div><div class="detail-main"><div class="detail-overline">${elBadge(e.id)} <span>• ${safe(current.tag)}</span></div><h2>${safe(current.name)}</h2><p class="team-summary">${safe(current.summary)}</p><div class="team-measures"><span>${icon('team',16)} 4-MEMBER SQUAD</span><span>${icon('check',16)} ${own}/4 IN COLLECTION</span><span>${icon('book',16)} SOURCE: GAMEWITH</span></div><div class="team-row">${line.map(([name,role,form])=>unitCard(name,role,form)).join('')}</div><div class="team-detail-actions"><button class="btn primary" data-load-team="${current.element}">${icon('layers',17)} Load in planner</button><button class="btn secondary" data-team-owned="${current.element}">${icon('plus',17)} Mark lineup owned</button><a class="btn ghost-link" target="_blank" rel="noopener noreferrer" href="https://gamewith.ai/aniimo/en/articles/best-team-comps">Original guide ${icon('external',16)}</a></div></div><aside class="detail-why"><div class="detail-aside-title">WHY IT WORKS</div>${current.strength.map((x,i)=>`<div class="plus-row"><span class="small-plus">0${i+1}</span><span>${safe(x)}</span></div>`).join('')}<div class="tactical-callout"><span>TACTICAL CONSIDERATION</span><p>${safe(current.risk)}</p></div><div class="owned-bar"><div><span>ROSTER READINESS</span><strong>${Math.round(own/4*100)}%</strong></div><div class="progress"><i style="width:${own/4*100}%"></i></div><small>${own} of 4 team members owned</small></div></aside></div><div class="secondary-grid"><section class="content-card"><div class="card-head"><span class="section-kicker">COMBAT FLOW</span><h3>Suggested rotation</h3></div><div class="rotation-list">${current.rotation.map((s,i)=>`<div class="rotation-step"><span>${String(i+1).padStart(2,'0')}</span><p>${safe(s)}</p></div>`).join('')}</div><div class="hint-block">${icon('spark',18)} <span>${safe(current.tip)}</span></div></section><section class="content-card"><div class="card-head"><span class="section-kicker">ADAPT YOUR SQUAD</span><h3>Recommended alternatives</h3></div><div class="alternatives">${current.alternatives.map(alt=>`<div class="alternative"><div class="alt-compare">${avatar(getAniimo(alt.out),'sm')}<span>${safe(alt.out)}</span>${icon('arrow',17)}${avatar(getAniimo(alt.in),'sm')}<strong>${safe(alt.in)}</strong></div><p>${safe(alt.why)}</p><button data-swap="${safe(current.element)}|${safe(alt.out)}|${safe(alt.in)}|${safe(alt.form)}" class="text-action">Load alternative ${icon('arrow',14)}</button></div>`).join('')}</div><div class="subnote">These recommendations are situation-dependent, not universally strongest.</div></section></div>`}
function library(){let units=ANIIMO.filter(a=>(state.rosterFilter==='All'||state.rosterFilter===a.element)&&(!state.rosterOwned||owned(a.name))&&a.name.toLowerCase().includes(state.rosterQuery.toLowerCase()));return `${title('ANIIDEX / 003','Build <em>intelligence.</em>','Search the curated Aniimo roster. Detailed builds are individually labeled; unverified entries show transparent role templates.',button('My owned Aniimo','collection','btn subtle'))}<section class="library-toolbar"><label class="search-wrap">${icon('search',19)}<input id="roster-search" type="search" placeholder="Search Aniimo by name..." value="${safe(state.rosterQuery)}" aria-label="Search Aniimo"></label><label class="select-wrap">ELEMENT <select id="roster-element"><option value="All">All elements</option>${ELEMENTS.map(e=>`<option value="${e.id}" ${state.rosterFilter===e.id?'selected':''}>${e.id}</option>`).join('')}</select></label><button class="toggle-filter ${state.rosterOwned?'on':''}" data-toggle="roster-owned">${icon('check',16)} Owned only</button></section><div class="library-summary"><span><b>${units.length}</b> / ${ANIIMO.length} curated entries</span><span><b>${Object.keys(BUILDS).length}</b> enhanced build profiles</span><span><b>9</b> researched teams</span></div><div class="library-grid">${units.map(a=>{const b=getBuild(a);return `<article class="library-card"><button class="library-open" data-open="${a.name}" aria-label="Open ${safe(a.name)}"><span class="lib-rune-bg">${getElement(a.element).symbol}</span>${avatar(a,'lg')}<div class="lib-title"><strong>${safe(a.name)}</strong><span>${safe(a.role)}</span></div></button><div class="lib-meta">${elBadge(a.element,true)}<span class="tag-quality ${b.quality.startsWith('Role')?'soft':''}">${b.quality.startsWith('Role')?'ROLE TEMPLATE':'GUIDED BUILD'}</span></div><div class="lib-footer"><button class="icon-button ${owned(a.name)?'owned':''}" data-owned="${safe(a.name)}" title="${owned(a.name)?'Remove from collection':'Add to collection'}">${icon(owned(a.name)?'check':'plus',17)}</button><button data-open="${a.name}" class="library-detail-link">Build details ${icon('arrow',15)}</button></div></article>`}).join('')}</div>${!units.length?`<div class="empty-state">${icon('search',27)}<h3>No Aniimo found</h3><p>Try another element or turn off “Owned only”.</p><button class="btn secondary" data-clear="filters">Reset filters</button></div>`:''}`}
function itemsPage(){return `${title('EQUIPMENT CODEX / 004','Held item <em>lab.</em>','Compare published item effects and role fit. BIS recommendations require checking each Aniimo\'s actual kit.',button('Open build library','aniidex','btn primary'))}<div class="gear-callout">${icon('info',20)}<div><strong>15 documented items, not 15 universal best-in-slot answers.</strong><p>Effects are summarized from the GameWith item index. Candidate uses are role-based interpretations unless an individual build source names the item.</p></div><a href="https://gamewith.ai/aniimo/en/held-items" target="_blank" rel="noopener noreferrer">Source ${icon('external',15)}</a></div><div class="item-grid">${ITEMS.map((item,i)=>`<article class="item-card"><div class="item-icon">${icon(item.main==='BREAK'?'shield':item.main==='HP'?'heart':item.main==='REGEN'?'refresh':'spark',25)}</div><span class="item-index">GEAR / ${String(i+1).padStart(2,'0')}</span><h3>${safe(item.name)}</h3><span class="item-main">${safe(item.main)}</span><p>${safe(item.effect)}</p><div class="item-roles"><small>BEST-FIT ROLE</small><strong>${safe(item.focus)}</strong></div><div class="item-rec">${icon('info',14)} ${safe(item.recommend)}</div></article>`).join('')}</div><section class="content-card item-guidance"><div><span class="section-kicker">EQUIPMENT STRATEGY</span><h3>How to pick the real best item</h3></div><p>Compare three factors: whether its passive triggers with your equipped skills, whether its stat scales your actual role, and whether it helps the full four-member rotation. A +15 passive may change the ranking. Equip your selected item in My Collection to record your setup.</p>${button('Open collection','collection','btn secondary')}</section>`}
function progression(){if(!state.selected||!getAniimo(state.selected)){return `${title('ASCENSION PATH / 005','Upgrade <em>roadmap.</em>','Select any Aniimo to review role priorities, build-specific advice, stat breakpoints, and Star Up planning.',button('Explore build library','aniidex','btn secondary'))}<div class="roadmap-top"><div><span class="section-kicker">CHOOSE YOUR TARGET</span><h2>Which Aniimo are you upgrading?</h2></div><label class="select-wrap large">SELECT ANIIMO<select id="progress-select"><option value="" selected>Choose an Aniimo...</option>${ANIIMO.map(u=>`<option value="${safe(u.name)}">${safe(u.name)}${owned(u.name)?' ✓':''}</option>`).join('')}</select></label></div><div class="empty-state upgrade-empty">${icon('spark',32)}<h3>Your next upgrade starts here</h3><p>Pick any entry in the selector above. No Aniimo or stats are preselected — your own roster stays yours.</p><button class="btn primary" data-nav="aniidex">${icon('book',16)} Browse Aniimo builds</button></div><div class="field-note">${icon('info',20)}<p>General stat priorities are starting points, not guarantees. Verify each creature’s actual skill scaling and current patch before spending rare awakening resources.</p></div>`;}const name=state.selected;const a=getAniimo(name),b=getBuild(a),role=ROLE_PRIORITIES[a.role],r=state.collection[name],lv=r?.level||0,star=r?.star||0,budget=r?.budget||0,spent=r?.spent||0,avail=Math.max(0,budget-spent);const major=b.stats.filter(x=>STAT_NAMES.includes(x));const next=major.find(x=>(r?.awaken?.[x]??0)<20);const nextVal=next?(r?.awaken?.[next]??0):null;const milestone=nextVal!==null?[4,8,12,16,20].find(v=>v>nextVal):null;return `${title('ASCENSION PATH / 005','Upgrade <em>roadmap.</em>','Prioritize irreversible awakenings, plan star-up gates and avoid investing materials based on unverified assumptions.',button('Open full profile','aniidex','btn secondary'))}<div class="roadmap-top"><div><span class="section-kicker">TARGET ANIIMO</span><h2>Ascension planning</h2></div><label class="select-wrap large">SELECT PROFILE<select id="progress-select">${ANIIMO.map(u=>`<option value="${safe(u.name)}" ${name===u.name?'selected':''}>${safe(u.name)}${owned(u.name)?' ✓':''}</option>`).join('')}</select></label></div><div class="progression-intro" style="--progress-tone:${getElement(a.element).tone}">${avatar(a,'xl')}<div class="progress-intro-copy"><div>${elBadge(a.element)} <span class="role-badge">${safe(a.role)}</span></div><h2>${safe(name)}</h2><p>${safe(b.notes)}</p><button class="text-action" data-open="${safe(name)}">View source-backed build & edit stats ${icon('arrow',16)}</button></div><div class="budget-figure"><span>AWAKENINGS AVAILABLE</span><strong>${owned(name)?avail:'—'}</strong><small>${owned(name)?`${spent} used / ${budget} budget`:'Add to your collection to personalize'}</small></div></div><div class="roadmap-grid"><section class="content-card"><span class="section-kicker">INVESTMENT QUEUE</span><h3>Prioritize these attributes</h3><div class="stat-priority-stack">${b.stats.map((st,i)=>`<div class="priority-point"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${safe(st)}</strong><p>${i===0?'Primary role scaling':i===1?'Secondary role efficiency':'Individual trait-dependent choice'}</p></div><span>${STAT_NAMES.includes(st)&&owned(name)?safe(String(r.awaken?.[st]??0))+'/20':'CHECK KIT'}</span></div>`).join('')}</div><div class="hint-block">${icon('info',17)}<span>${safe(b.third)} ${safe(role.avoid)}</span></div>${owned(name)?`<div class="planned-next"><span class="section-kicker">NEXT INVESTMENT</span><p>${next&&milestone?`Consider ${safe(next)} toward total Potential ${milestone}. Confirm star bonuses and actual in-game point cost.`:'Primary documented priorities are complete. Preserve remaining points until a specific encounter or trait justifies a third stat.'}</p></div>`:''}</section><section class="content-card"><span class="section-kicker">STAR UP CHECKLIST</span><h3>Verify each unlock per Aniimo</h3><div class="star-track">${[{label:'CURRENT STAR',desc:'Record your actual Star Up level.',value:owned(name)?String(star):'—'},{label:'LEVEL REQUIREMENT',desc:'Check the next Star Up level gate in game.',value:'CHECK'},{label:'MATERIAL REQUIREMENTS',desc:'Check the required items and quantities in game.',value:'CHECK'},{label:'AWAKENING CAPACITY',desc:'Record the new cap after Star Up in your profile.',value:owned(name)?String(budget):'—'}].map(x=>`<div class="star-milestone"><span>${icon('spark',17)}</span><div><strong>${x.label}</strong><small>${x.desc}</small></div><b>${x.value}</b></div>`).join('')}</div><div class="tiny-advisory">${icon('alert',17)} The cited tests report that awakening resets are unavailable above level 60. Verify the latest rules before leveling past this point.</div></section></div><section class="content-card breakpoint-card"><span class="section-kicker">BREAKPOINT INTELLIGENCE</span><h3>Spend in meaningful steps</h3><p>Based on the cited test data, total Potential bonuses are larger at the fourth-point intervals. Star-up bonuses can shift the number of purchased points required. Always read the total displayed in game.</p><div class="breakpoint-row">${[4,8,12,16,20].map(x=>`<span>${x}<small> TOTAL</small></span>`).join('')}</div><div class="sources-foot">${sourceLinks(['guide-stats'])}</div></section>`}
function personalPanel(name){const a=getAniimo(name);if(!a)return '';const profile=state.collection[name]||clone(DEFAULT_PROFILE);const aw={...DEFAULT_PROFILE.awaken,...(profile.awaken||{})};const f=(k,lab,mi,ma)=>`<label class="form-field"><span>${lab}</span><input type="number" data-profile="${safe(name)}" data-field="${k}" min="${mi}" max="${ma}" value="${n(profile[k],mi,ma,k==='level'?1:0)}" /></label>`;return `<div class="edit-panel"><div class="panel-heading"><div><span class="section-kicker">PERSONAL SAVE</span><h3>${safe(name)} progression</h3></div><span class="data-local">${icon('shield',14)} DEVICE ONLY</span></div><div class="profile-fields">${f('level','LEVEL',1,100)}${f('cp','COMBAT POWER',0,999999)}${f('star','STAR UP',0,12)}${f('spent','POINTS SPENT',0,200)}${f('budget','AWAKEN BUDGET',0,200)}<label class="form-field"><span>POTENTIAL</span><select data-profile="${safe(name)}" data-field="potential">${['Unknown','Common','Good','Excellent','Perfect'].map(v=>`<option ${profile.potential===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="edit-caption">RECORDED POTENTIAL VALUES <span>0–20 (edit directly from your game)</span></div><div class="stat-grid">${STAT_NAMES.map(st=>`<label class="stat-input"><span>${safe(st)}</span><input type="number" min="0" max="20" data-profile="${safe(name)}" data-awaken="${safe(st)}" value="${n(aw[st],0,20,0)}"><span class="stat-track"><i style="width:${n(aw[st],0,20,0)*5}%"></i></span></label>`).join('')}</div><div class="profile-fields extra"><label class="form-field wide"><span>YOUR HELD ITEM</span><input data-profile="${safe(name)}" data-field="held" value="${safe(profile.held||'')}" placeholder="e.g. Heartseeker Pendant +15"></label><label class="form-field wide"><span>NOTES</span><textarea data-profile="${safe(name)}" data-field="notes" rows="2" placeholder="Build notes, trait, unlocks...">${safe(profile.notes||'')}</textarea></label></div><button class="btn primary save-profile" data-save-profile="${safe(name)}">${icon('save',17)} Save progression</button></div>`}
function sourceLinks(ids){return `<div class="source-links">${ids.map(id=>{const s=source(id);return s?`<a href="${safe(s.url)}" target="_blank" rel="noopener noreferrer">${safe(s.name)} ${icon('external',13)}</a>`:''}).join('')}</div>`}
function buildDetail(name){const a=getAniimo(name);if(!a)return '';const b=getBuild(a),record=state.collection[name],r=ROLE_PRIORITIES[a.role]||ROLE_PRIORITIES.Support;return `<div class="build-overlay" data-close="modal"><section class="build-sheet" role="dialog" aria-modal="true" aria-label="${safe(name)} build"><div class="sheet-bar"><span>ANIIMO INTELLIGENCE / ${safe(a.name).toUpperCase()}</span><button class="close-btn" data-close="modal" aria-label="Close">${icon('x',21)}</button></div><div class="sheet-head" style="--sheet-tone:${getElement(a.element).tone}"><div class="sheet-glow"></div>${avatar(a,'xl')}<div class="sheet-info"><div>${elBadge(a.element)} <span class="role-badge">${safe(a.role)}</span></div><h2>${safe(a.name)}</h2><span class="quality-tag">${icon('info',15)} ${safe(b.quality)}</span></div></div><div class="sheet-scroll"><div class="sheet-action-line"><span>${record?.owned?'In your collection':'Not in your collection'}</span><button class="btn ${record?.owned?'secondary':'primary'}" data-owned="${safe(name)}">${icon(record?.owned?'check':'plus',16)} ${record?.owned?'Remove from collection':'Add to collection'}</button></div><p class="sheet-intro">${safe(b.notes)}</p><div class="build-facts"><div><small>HELD ITEM</small><strong>${safe(b.item)}</strong><span>Alternative: ${safe(b.altItem)}</span></div><div><small>AWAKENING ORDER</small><strong>${safe(b.stats.join(' → '))}</strong><span>${safe(b.third)}</span></div><div><small>PERSONALITY</small><strong>${safe(b.personality)}</strong><span>${safe(b.form)}</span></div><div><small>ACTIVE SKILLS</small><strong>${b.skills.length?b.skills.map(safe).join(' + '):'Not individually verified'}</strong><span>${b.innate?'Innate: '+safe(b.innate):'Check current in-game loadout'}</span></div></div><h3 class="sheet-section">Battle plan</h3><p class="detail-description">${safe(b.rotation)}</p><h3 class="sheet-section">Role investment policy</h3><div class="policy-line">${icon('chart',18)}<p>${safe(r.explain)} <strong>${safe(r.avoid)}</strong></p></div><h3 class="sheet-section">References & confidence</h3>${sourceLinks(b.sources)}${personalPanel(name)}</div></section></div>`}
// Transparency-focused checklist; it is not a computed DPS, win rate, or performance prediction.
function gradeTeam(names){const selected=names.map(getAniimo).filter(Boolean);const ref=TEAMS.find(t=>t.element===state.target);const roles=selected.map(a=>ref?.lineup.find(([name])=>name===a.name)?.[1]||a.role);const uniq=new Set(selected.map(a=>a.name));let issues=[];let pts=0;if(roles.includes('DPS'))pts+=20;else issues.push('No primary DPS');if(roles.includes('Break'))pts+=20;else issues.push('No dedicated breaker (some supports can BREAK)');if(roles.includes('Regen'))pts+=20;else issues.push('No REGEN role');if(roles.includes('Heal'))pts+=15;else issues.push('No dedicated healer');if(roles.includes('Support'))pts+=10;else issues.push('No explicit support role');pts+=Math.round(selected.length/4*10);if(uniq.size!==selected.length){issues.push('Duplicate Aniimo selected');pts=Math.max(0,pts-15)}let own=selected.filter(a=>owned(a.name)).length;pts+=Math.round(own/4*5);return {pts:Math.min(100,pts),issues,selected,own}}
function planner(){let lineup=state.teamNames.map(n=>n||'');let current=gradeTeam(lineup);const rec=TEAMS.find(t=>t.element===state.target)||TEAMS[0];return `${title('BUILD ENGINE / 004','Squad <em>optimizer.</em>','Plan a four-Aniimo composition, check roles and ownership, then compare it with research-backed team templates.',button('Browse sources','sources','btn subtle','external'))}<div class="planner-head"><div><span class="section-kicker">SQUAD BUILDER</span><h2>Forge your four-member team</h2><p>Composition health scores reflect roles and collection readiness — not predicted combat damage.</p></div><div class="select-wrap large"><label for="team-preset">TEAM PRESET</label><select id="team-preset">${TEAMS.map(t=>`<option value="${t.element}" ${t.element===state.target?'selected':''}>${t.element} · ${t.name}</option>`).join('')}</select></div></div><div class="planner-layout"><div><section class="planner-canvas"><div class="planner-top"><span>ACTIVE SQUAD <i>4 SLOTS</i></span><button class="mini-link" data-load-team="${state.target}">${icon('refresh',15)} Load ${safe(state.target)} recommendation</button></div><div class="planner-slots">${[0,1,2,3].map((i)=>{const name=lineup[i],a=getAniimo(name),el=a?getElement(a.element):null;return `<div class="planner-slot"><div class="slot-top"><span>0${i+1} / ${['CARRY','SUPPORT','UTILITY','FLEX'][i]}</span>${name&&owned(name)?'<span class="slot-owned">OWNED</span>':''}</div><div class="slot-avatar">${a?avatar(a,'lg'):`<span class="slot-empty">${icon('plus',30)}</span>`}</div><select class="slot-select" data-slot="${i}" aria-label="Select team slot ${i+1}"><option value="">Select Aniimo...</option>${ANIIMO.map(u=>`<option value="${safe(u.name)}" ${name===u.name?'selected':''}>${safe(u.name)}${owned(u.name)?' ✓':''}</option>`).join('')}</select>${a?`<div class="slot-roles">${elBadge(a.element,true)} <span>${safe(a.role)}</span></div>`:`<div class="slot-roles">OPEN SLOT</div>`}</div>`}).join('')}</div><div class="planner-actions"><button class="btn primary" data-analyze="team">${icon('chart',17)} Analyze composition</button><button class="btn secondary" data-clear="team">${icon('refresh',16)} Reset squad</button></div></section><section class="content-card tactical-panel"><span class="section-kicker">RESEARCH TEMPLATE</span><h3>${safe(rec.name)}</h3><p>${safe(rec.summary)}</p><div class="horizontal-members">${rec.lineup.map(([name,role])=>`<div>${avatar(getAniimo(name),'sm')}<span><strong>${safe(name)}</strong><small>${safe(role)}</small></span></div>`).join('')}</div><button class="text-action" data-team="${safe(rec.element)}">See full ${safe(rec.element)} strategy ${icon('arrow',15)}</button></section></div><div><div class="analysis-card"><div class="analysis-head"><span class="section-kicker">COMPOSITION CHECKLIST</span><span class="heuristic-badge">HEURISTIC</span></div><div class="analysis-score"><div class="score-ring" style="--score:${current.pts}"><div><strong>${current.pts}</strong><span>/100</span></div></div><div><h3>${current.pts>=80?'Well-rounded roles':current.pts>=55?'Some role gaps':'Needs revision'}</h3><p>Role coverage + owned readiness</p></div></div><div class="analysis-divider"></div><div class="analysis-row"><span>DPS carry</span><strong class="${current.selected.some(a=>a.role==='DPS')?'positive':'negative'}">${current.selected.some(a=>a.role==='DPS')?'COVERED':'MISSING'}</strong></div><div class="analysis-row"><span>BREAK</span><strong class="${current.selected.some(a=>a.role==='Break')?'positive':'negative'}">${current.selected.some(a=>a.role==='Break')?'COVERED':'REVIEW'}</strong></div><div class="analysis-row"><span>Energy / REGEN</span><strong class="${current.selected.some(a=>a.role==='Regen')?'positive':'negative'}">${current.selected.some(a=>a.role==='Regen')?'COVERED':'MISSING'}</strong></div><div class="analysis-row"><span>Healing</span><strong class="${current.selected.some(a=>a.role==='Heal')?'positive':'negative'}">${current.selected.some(a=>a.role==='Heal')?'COVERED':'OPTIONAL'}</strong></div><div class="analysis-row"><span>Owned members</span><strong>${current.own} / 4</strong></div><div class="analysis-alert">${icon('alert',18)}<span>${current.issues.length?safe(current.issues[0]):'All major checklist criteria covered. Confirm elemental weaknesses manually.'}</span></div><p class="analysis-disclaimer">This is a transparent composition checklist, not a DPS simulator. Team forms can change combat roles and elemental coverage.</p></div><div class="content-card about-awakening"><span class="section-kicker">UPGRADE INTELLIGENCE</span><h3>Maximize your resources</h3><p>Role-first investment, then specific skill scaling. Stat breakpoints commonly occur at total Potential 4, 8, 12, 16 and 20.</p><div class="priority-list">${[['DPS','ATK → REGEN'],['BREAK','BREAK → REGEN'],['REGEN','REGEN'],['HEAL','HP'],['SUPPORT','Trait-dependent']].map(([role,prio])=>`<div><span>${role}</span><strong>${prio}</strong></div>`).join('')}</div><div class="tiny-advisory">${icon('info',17)} Reset restrictions above Lv. 60 are reported in current guide data; check in game before spending.</div></div></div></div>`}
function collection(){const records=ANIIMO.filter(a=>owned(a.name));const l60=records.filter(a=>(state.collection[a.name].level||1)>=60).length;return `${title('PERSONAL VAULT / 005','My <em>collection.</em>','Track your actual roster, progression, held items and awakenings. Data stays in this browser until you export it.',`<button class="btn secondary" data-action="export">${icon('download',17)} Export JSON</button><button class="btn primary" data-action="import">${icon('upload',17)} Import JSON</button>`) }<div class="vault-stats"><div>${icon('layers',22)}<div><small>OWNED ANIIMO</small><strong>${records.length}<em> / ${ANIIMO.length}</em></strong></div></div><div>${icon('spark',22)}<div><small>LEVEL 60+</small><strong>${l60}</strong></div></div><div>${icon('target',22)}<div><small>TRACKED BUILDS</small><strong>${records.filter(a=>Object.keys(BUILDS).includes(a.name)).length}</strong></div></div><div>${icon('shield',22)}<div><small>STORAGE</small><strong class="storage-label">LOCAL ONLY</strong></div></div></div><div class="section-heading"><div><span class="section-kicker">YOUR UNITS</span><h2>Collection registry</h2></div>${button('Add Aniimo','aniidex','btn subtle','plus')}</div>${records.length?`<div class="collection-grid">${records.map(a=>{let p=state.collection[a.name];return `<div class="collection-card">${avatar(a,'lg')}<div class="collection-body"><div class="collection-title"><h3>${safe(a.name)}</h3>${elBadge(a.element,true)}</div><div class="collection-stats"><span>LEVEL <strong>${n(p.level,1,100,1)}</strong></span><span>CP <strong>${n(p.cp,0,999999,0).toLocaleString('en-US')}</strong></span><span>STAR <strong>${n(p.star,0,12,0)}</strong></span></div><div class="collection-actions"><button class="btn secondary" data-open="${safe(a.name)}">${icon('edit',16)} Edit profile</button><button class="icon-button" data-owned="${safe(a.name)}" title="Remove from collection">${icon('x',18)}</button></div></div></div>`}).join('')}</div>`:`<div class="empty-state">${icon('layers',30)}<h3>Your vault is empty</h3><p>Add Aniimo from the library and their builds will appear here.</p>${button('Browse library','aniidex','btn primary')}</div>`}<section class="data-actions"><div><span class="section-kicker">BACKUP & PORTABILITY</span><h3>Own your progression data</h3><p>Export anytime to move between your PC and phone. The app never uploads your collection to a server.</p></div><div><button class="btn secondary" data-action="export">${icon('download',16)} Download backup</button><button class="btn danger" data-action="reset">${icon('refresh',16)} Reset collection</button></div></section>`}
function sources(){return `${title('RESEARCH NETWORK / 006','Source <em>transparency.</em>','Every recommendation is connected to public references. Research snapshots are curated, not a live official API.',button('View builds','aniidex','btn primary'))}<div class="source-summary"><div>${icon('database',26)}<strong>${SOURCES.length}</strong><span>reference links</span></div><div>${icon('team',26)}<strong>09</strong><span>elemental presets</span></div><div>${icon('book',26)}<strong>${ANIIMO.length}</strong><span>indexed Aniimo</span></div><div>${icon('shield',26)}<strong>LOCAL</strong><span>personal data</span></div></div><section class="content-card"><div class="card-head"><span class="section-kicker">SOURCE REGISTRY</span><h3>Where recommendations come from</h3></div><div class="sources-table">${SOURCES.map(s=>`<div class="source-row"><div class="source-symbol">${icon('book',20)}</div><div><h4>${safe(s.name)}</h4><p>${safe(s.note)}</p><span class="source-cat">${safe(s.category)}</span></div><div class="source-date">${safe(s.date)}</div><a href="${safe(s.url)}" target="_blank" rel="noopener noreferrer" title="Visit reference">${icon('external',19)}</a></div>`).join('')}</div></section><div class="secondary-grid"><section class="content-card"><span class="section-kicker">RELIABILITY POLICY</span><h3>How data is classified</h3><div class="reliability"><div><span class="reliability-mark confirmed"></span><strong>Detailed / source-backed</strong><p>Individual skill/item information checked against named guides or game-derived data.</p></div><div><span class="reliability-mark community"></span><strong>Community-tested</strong><p>Player builds and team lineups. Can vary by patch, encounter and equipment.</p></div><div><span class="reliability-mark template"></span><strong>Role template</strong><p>Generic ATK / REGEN / BREAK / HP advice; never presented as a verified creature-specific BIS setup.</p></div></div></section><section class="content-card"><span class="section-kicker">DATA OPERATIONS</span><h3>What updates automatically?</h3><p>Collection edits and team comparisons run immediately in your browser. The published guide dataset is a dated, manually curated snapshot; it does not silently scrape websites or claim real-time updates.</p><div class="hint-block">${icon('info',18)} <span>To update the research, edit <code>assets/data.js</code> and redeploy. You can import and export personal progression using JSON.</span></div><a class="inline-link" target="_blank" rel="noopener noreferrer" href="https://gamewith.ai/aniimo/en/articles/best-team-comps">Check the newest team guidance ${icon('external',16)}</a></section></div>`}
function render(keepScroll=false){const was=window.scrollY;document.querySelectorAll('.build-overlay').forEach(el=>el.remove());app.innerHTML=header()+({overview,teams:teamsPage,aniidex:library,items:itemsPage,progression,planner,collection,sources}[state.nav]||overview)()+footer();if(modal){document.body.insertAdjacentHTML('beforeend',buildDetail(modal));document.body.classList.add('modal-open')}else{document.body.classList.remove('modal-open')}if(keepScroll)requestAnimationFrame(()=>window.scrollTo(0,was));else requestAnimationFrame(()=>window.scrollTo(0,0))}
function navigate(page){state.nav=page;document.body.classList.remove('menu-open');render();persist()}
function openBuild(name){if(!getAniimo(name))return;modal=name;render(true)}
function closeBuild(){modal=null;document.querySelector('.build-overlay')?.remove();document.body.classList.remove('modal-open');render(true)}
function toggleOwned(name){if(!getAniimo(name))return;if(owned(name)){delete state.collection[name];flash(`${name} removed from collection.`)}else{state.collection[name]=clone(DEFAULT_PROFILE);flash(`${name} added to collection.`)}persist();render(true)}
function saveProfile(name){const dialog=document.querySelector('.build-sheet');if(!dialog)return;const base=clone(state.collection[name]||DEFAULT_PROFILE);dialog.querySelectorAll('[data-profile]').forEach(input=>{if(input.dataset.awaken)base.awaken[input.dataset.awaken]=n(input.value,0,20,0);else {const k=input.dataset.field;if(['level','cp','star','spent','budget'].includes(k))base[k]=n(input.value,k==='level'?1:0,k==='cp'?999999:k==='level'?100:200);else base[k]=input.value.slice(0,k==='notes'?400:120)}});base.owned=true;if(base.spent>base.budget){flash('Spent exceeds budget — check your game screenshot.','warn');return}state.collection[name]=base;persist();flash(`${name} progression saved.`);render(true)}
function loadTeam(ele){const t=TEAMS.find(x=>x.element===ele)||TEAMS[0];state.target=t.element;state.teamNames=t.lineup.map(x=>x[0]);persist();navigate('planner');flash(`${t.element} team loaded in planner.`)}
function swapTeam(value){const [element,outN,inN,form]=value.split('|');const t=TEAMS.find(x=>x.element===element);if(!t)return;state.target=element;state.teamNames=t.lineup.map(x=>x[0]===outN?inN:x[0]);navigate('planner');flash(`${outN} swapped for ${inN}${form&&form!=='Basic'?' ('+form+')':''}.`)}
function downloadBackup(){const obj={format:'aniimo-center',version:1,exportedAt:new Date().toISOString(),collection:state.collection,favorite:state.favorite};const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download='aniimo-center-backup.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);flash('Backup exported successfully.')}
function importBackup(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{if(file.size>2500000)throw new Error('File is too large');const b=JSON.parse(String(reader.result));if(b.format!=='aniimo-center'||b.version!==1||!b.collection||typeof b.collection!=='object'||Array.isArray(b.collection))throw new Error('Not a valid ANIIMO CENTER backup');const cleaned={};Object.entries(b.collection).forEach(([name,p])=>{if(!getAniimo(name)||!p||typeof p!=='object')return;cleaned[name]={...clone(DEFAULT_PROFILE),owned:true,level:n(p.level,1,100,1),cp:n(p.cp,0,999999,0),star:n(p.star,0,12,0),spent:n(p.spent,0,200,0),budget:n(p.budget,0,200,5),potential:String(p.potential||'Unknown').slice(0,50),held:String(p.held||'').slice(0,120),notes:String(p.notes||'').slice(0,400),awaken:Object.fromEntries(STAT_NAMES.map(st=>[st,n(p.awaken?.[st],0,20,0)]))}});state.collection=cleaned;persist();render(true);flash(`Imported ${Object.keys(cleaned).length} owned Aniimo.`)}catch(err){flash('Import failed: '+err.message,'warn')}};reader.readAsText(file)}
const uploader=document.createElement('input');uploader.type='file';uploader.accept='application/json,.json';uploader.hidden=true;document.body.appendChild(uploader);uploader.addEventListener('change',e=>{importBackup(e.target.files[0]);uploader.value=''})
document.addEventListener('click',e=>{const target=e.target.closest('button,a,[data-close],[data-toggle]');if(!target)return;if(target.dataset.close){if(e.target===target||target.tagName==='BUTTON')closeBuild();return}if(target.dataset.toggle==='menu'){document.body.classList.toggle('menu-open');return}if(target.dataset.toggle==='roster-owned'){state.rosterOwned=!state.rosterOwned;render(true);return}if(target.dataset.nav){navigate(target.dataset.nav);return}if(target.dataset.open){openBuild(target.dataset.open);return}if(target.dataset.team){state.target=target.dataset.team;navigate('teams');return}if(target.dataset.owned){toggleOwned(target.dataset.owned);return}if(target.dataset.loadTeam){loadTeam(target.dataset.loadTeam);return}if(target.dataset.swap){swapTeam(target.dataset.swap);return}if(target.dataset.teamOwned){const t=TEAMS.find(x=>x.element===target.dataset.teamOwned);let count=0;t?.lineup.forEach(([name])=>{if(!owned(name)){state.collection[name]=clone(DEFAULT_PROFILE);count++}});persist();render(true);flash(count?`${count} Aniimo added to collection.`:'All team members already owned.');return}if(target.dataset.saveProfile){saveProfile(target.dataset.saveProfile);return}if(target.dataset.analyze){flash('Role checklist updated from your selected lineup.');return}if(target.dataset.clear==='team'){state.teamNames=['','','',''];persist();render(true);return}if(target.dataset.clear==='filters'){state.rosterQuery='';state.rosterFilter='All';state.rosterOwned=false;render(true);return}if(target.dataset.action==='export'){downloadBackup();return}if(target.dataset.action==='import'){uploader.click();return}if(target.dataset.action==='reset'){if(window.confirm('Clear the entire ANIIMO collection stored in this browser? Export a backup first.')){state.collection={};persist();render();flash('Collection reset.')}}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='roster-element'){state.rosterFilter=t.value;render(true)}if(t.id==='progress-select'){state.selected=t.value;persist();render(true)}if(t.id==='team-preset'){state.target=t.value;state.teamNames=(TEAMS.find(a=>a.element===t.value)||TEAMS[0]).lineup.map(x=>x[0]);persist();render(true)}if(t.dataset.slot!==undefined){state.teamNames[Number(t.dataset.slot)]=t.value;persist();render(true)}});
document.addEventListener('input',e=>{if(e.target.id==='roster-search'){let active=e.target,idx=active.selectionStart;state.rosterQuery=active.value;const grid=document.querySelector('.library-grid');const summary=document.querySelector('.library-summary');if(!grid)return;let filtered=ANIIMO.filter(a=>(state.rosterFilter==='All'||state.rosterFilter===a.element)&&(!state.rosterOwned||owned(a.name))&&a.name.toLowerCase().includes(state.rosterQuery.toLowerCase()));grid.querySelectorAll('.library-card').forEach(card=>{const name=card.querySelector('[data-open]')?.dataset.open;card.style.display=filtered.some(a=>a.name===name)?'':'none'});if(summary)summary.querySelector('b').textContent=filtered.length;const emp=document.querySelector('.library-empty-search');if(emp)emp.remove();if(!filtered.length)grid.insertAdjacentHTML('afterend','<p class="library-empty-search muted">No matching Aniimo. Try a different search.</p>')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal)closeBuild();document.body.classList.remove('menu-open')}});
render();
